              "findingId": {
                "type": "string"
              },
              "section": {
                "type": "string"
              },
              "adequacy": {
                "type": "string"
              },
              "summary": {
                "type": "string"
              },
              "whyItMatters": {
                "type": "string"
              },
              "relatedRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "recommendedAction": {
                "type": "string"
              },
              "requiresHumanDecision": {
                "type": "boolean"
              }
            },
            "required": [
              "findingId",
              "section",
              "adequacy",
              "summary",
              "whyItMatters",
              "relatedRequirementIds",
              "recommendedAction",
