        "arguments": {
          "findings": [
            {
              "findingId": "AF-001",
              "section": "Scope und Nicht-Ziele",
              "adequacy": "blocked_by_decision",
              "summary": "Der Scope ist für den Projektstart nicht ausreichend fixiert, weil die zentrale MVP-Abgrenzung zwischen Unterstützungswerkzeug und möglicher Dokumentationsübernahme offen ist.",
              "whyItMatters": "Ohne verbindliche Scope-Entscheidung können Funktionsumfang, Datenschutzbedarf, Rollenmodell, Datenmodell und Aufwand nicht stabil geplant werden. Ein Projektstart mit offener Hauptabgrenzung erzeugt hohes Rework-Risiko.",
              "relatedRequirementIds": [
                "CAN-REQ-001",
                "CAN-REQ-054",
                "CAN-REQ-055",
                "CAN-REQ-047"
              ],
              "recommendedAction": "Vor Start eine kurze, verbindliche Scope-Entscheidung mit expliziten Nicht-Zielen dokumentieren und die betroffenen Kapitel dagegen prüfen.",
              "requiresHumanDecision": true
            },
            {
              "findingId": "AF-002",
              "section": "Nutzerrollen und Berechtigungen",
              "adequacy": "thin",
              "summary": "Grundlegende Rollen sind vorhanden, aber das Berechtigungskonzept ist für die Umsetzung noch zu grob und nicht funktionsbezogen vollständig operationalisiert.",
              "whyItMatters": "Gerade bei Bewohnerdaten, Angehörigenzugriff, Admin-Funktionen und einrichtungsbezogener Trennung muss für jeden Funktionsbereich klar sein, wer sehen, anlegen, bearbeiten, freigeben, exportieren, verbergen und löschen darf. Sonst sind Security-, UI- und Backend-Design nicht belastbar startbar.",
              "relatedRequirementIds": [
                "CAN-REQ-002",
                "CAN-REQ-016",
                "CAN-REQ-017",
                "CAN-REQ-044",
                "CAN-REQ-045",
                "CAN-REQ-046",
                "CAN-REQ-048",
                "CAN-REQ-049"
              ],
              "recommendedAction": "Eine Rollen-Rechte-Matrix je Rolle und Funktionsbereich erstellen, inklusive Hausgrenzen, Sonderfällen für Angehörige/Bewohner und Admin-Operationen.",
              "requiresHumanDecision": true
            },
            {
              "findingId": "AF-003",
              "section": "Funktionale Anforderungen",
              "adequacy": "substantive",
              "summary": "Der funktionale Kern für ein Unterstützungswerkzeug ist gut erkennbar: Profilübersicht, About-Me, No-Go, Kommunikationsbereiche, Medien und Suchbedarf sind grundsätzlich beschrieben.",
              "whyItMatters": "Damit ist ein umsetzbarer Produktkern sichtbar, der den primären Nutzen 'Bewohner besser verstehen' stützt. Für den Projektstart reicht dies als fachliche Leitplanke, auch wenn einzelne Anforderungen noch verfeinert werden müssen.",
              "relatedRequirementIds": [
                "CAN-REQ-013",
                "CAN-REQ-015",
                "CAN-REQ-024",
                "CAN-REQ-025",
                "CAN-REQ-027",
                "CAN-REQ-028",
                "CAN-REQ-030",
                "CAN-REQ-032",
                "CAN-REQ-033",
                "CAN-REQ-035",
                "CAN-REQ-056",
                "CAN-REQ-057"
              ],
              "recommendedAction": "Den funktionalen Kern als MVP-Kandidaten bündeln und nur die fachlich offenen Teilbereiche separat nachschärfen, statt den Gesamtkern erneut breit zu diskutieren.",
              "requiresHumanDecision": false
            },
            {
              "findingId": "AF-004",
              "section": "UI/UX Anforderungen",
              "adequacy": "thin",
              "summary": "Es gibt eine klare Grundstruktur der Screens, aber wesentliche Nutzungs- und Bedienkriterien sind noch offen oder nur als gewünschte Ausgestaltung formuliert.",
              "whyItMatters": "Für einen Projektstart fehlen belastbare Leitplanken zu Nutzungskontext, Tablet-Support, Suchinteraktion, Layout-Varianten und barrierefreier Bedienbarkeit. Dadurch bleiben Informationsarchitektur, Komponentenwahl und Testfokus unscharf.",
              "relatedRequirementIds": [
                "CAN-REQ-018",
                "CAN-REQ-019",
                "CAN-REQ-020",
                "CAN-REQ-021",
                "CAN-REQ-023",
                "CAN-REQ-026",
